import React, { useState, useEffect, useRef } from 'react';
import { Canvas, useFrame, useThree } from '@react-three/fiber';
import { OrbitControls } from '@react-three/drei';
import { OBJLoader } from 'three/examples/jsm/loaders/OBJLoader';
import * as THREE from 'three';

// List of models assuming they are in the public/stls folder
const availableModels = [
  'model.obj',
  'model2.obj', // Make sure to add all model file names here
];

const ModelLoader = ({ modelPath }) => {
  const [model, setModel] = useState(null);
  const groupRef = useRef(null);

  useEffect(() => {
    const loader = new OBJLoader();
    const newModelRef = new THREE.Group(); // Create a new group for each model
    loader.load(
      modelPath,
      (obj) => {
        // Clean up the previous model
        if (model) {
          model.traverse((child) => {
            if (child.isMesh) {
              child.geometry.dispose();
              if (child.material.isMaterial) {
                child.material.dispose();
              }
            }
          });
        }

        // Calculate bounding box and adjust size
        const box = new THREE.Box3().setFromObject(obj);
        const size = box.getSize(new THREE.Vector3());
        const maxDimension = Math.max(size.x, size.y, size.z);
        obj.rotation.x = -Math.PI / 2;
        const scaleFactor = 2.5 / maxDimension;

        obj.scale.set(scaleFactor, scaleFactor, scaleFactor);

        // Center the model
        box.setFromObject(obj);
        const center = box.getCenter(new THREE.Vector3());
        obj.position.sub(center);

        // Add edge lines to meshes
        obj.traverse((child) => {
          if (child.isMesh) {
            const edges = new THREE.EdgesGeometry(child.geometry, 45);
            const lineMaterial = new THREE.LineBasicMaterial({
              color: 0xffffff,
              opacity: 0.5,
              transparent: true
            });
            const edgeLines = new THREE.LineSegments(edges, lineMaterial);

            edgeLines.position.copy(child.position);
            edgeLines.rotation.copy(child.rotation);
            edgeLines.scale.copy(child.scale);

            child.parent.add(edgeLines);
            child.parent.remove(child);
          }
        });

        // Set the new model
        newModelRef.add(obj);
        setModel(newModelRef); // Update the state with the new model
      },
      undefined,
      (error) => {
        console.error('Error loading OBJ:', error);
      }
    );

    // Cleanup on model change
    return () => {
      if (model) {
        model.traverse((child) => {
          if (child.isMesh) {
            child.geometry.dispose();
            if (child.material.isMaterial) {
              child.material.dispose();
            }
          }
        });
      }
    };
  }, [modelPath]);

  useFrame(() => {
    if (groupRef.current) {
      groupRef.current.rotation.y += 0.003;
    }
  });

  return (
    <group ref={groupRef}>
      {!model && (
        <mesh>
          <boxGeometry args={[1, 1, 1]} />
          <meshBasicMaterial color="white" wireframe={true} />
        </mesh>
      )}
      {model && <primitive object={model} />}
    </group>
  );
};

const App = () => {
  const [selectedModel, setSelectedModel] = useState(availableModels[0]);
  const [highlightedModel, setHighlightedModel] = useState(null);

  const handleKeyPress = (event) => {
    const currentIndex = availableModels.indexOf(selectedModel);
    if (event.key === 'ArrowDown') {
      const nextIndex = (currentIndex + 1) % availableModels.length;
      setSelectedModel(availableModels[nextIndex]);
    } else if (event.key === 'ArrowUp') {
      const prevIndex = (currentIndex - 1 + availableModels.length) % availableModels.length;
      setSelectedModel(availableModels[prevIndex]);
    }
  };

  useEffect(() => {
    window.addEventListener('keydown', handleKeyPress);
    return () => {
      window.removeEventListener('keydown', handleKeyPress);
    };
  }, [selectedModel]);

  const handleModelClick = (model) => {
    setSelectedModel(model);
  };

  return (
    <div style={{ display: 'flex' }}>
      {/* Left Sidebar */}
      <div
        style={{
          width: '200px',
          height: '100vh',
          backgroundColor: '#333',
          padding: '20px',
          color: 'white',
          overflowY: 'auto',
        }}
      >
        <h3>Select a Model</h3>
        <ul style={{ listStyle: 'none', paddingLeft: 0 }}>
          {availableModels.map((model, index) => (
            <li
              key={model}
              style={{
                padding: '10px',
                cursor: 'pointer',
                backgroundColor: selectedModel === model ? '#555' : '',
                color: selectedModel === model ? 'lightred' : 'white',
                fontWeight: highlightedModel === model ? 'bold' : 'normal',
              }}
              onClick={() => handleModelClick(model)}
              onMouseEnter={() => setHighlightedModel(model)}
              onMouseLeave={() => setHighlightedModel(null)}
            >
              {model}
            </li>
          ))}
        </ul>
      </div>

      {/* 3D Canvas */}
      <div style={{ flex: 1, height: '100vh' }}>
        <Canvas
          style={{ backgroundColor: 'black' }}
          camera={{
            position: [2.5, 2.5, 2.5],
            fov: 45,
          }}
        >
          <ambientLight intensity={0.5} />
          <spotLight position={[10, 10, 10]} intensity={1} />
          <directionalLight position={[5, 5, 5]} intensity={1} />
          {/* Load model from the public folder */}
          <ModelLoader modelPath={`./stls/${selectedModel}`} />
          <OrbitControls
            enableZoom={false}
            minPolarAngle={Math.PI / 4}
            maxPolarAngle={Math.PI / 4}
            minAzimuthAngle={-Math.PI / 4}
            maxAzimuthAngle={Math.PI / 4}
          />
        </Canvas>
      </div>
    </div>
  );
};

export default App;
